<div id="claim-form">
    <label for="policy-number">Policy Number</label>
    <input type="text" id="policy-number" required>
    <label for="member-id">Member ID</label>
    <input type="text" id="member-id" required>
    <button type="button" onclick="lookupMember()">Look up member</button>
    <div id="member-details"></div>
    <label for="last-day-worked">Last Day Worked</label>
    <input type="date" id="last-day-worked" required>
    <label for="first-day-absent">First Day Absent</label>
    <input type="date" id="first-day-absent" required>
    <label for="nature-of-absence">Nature of Absence</label>
    <select id="nature-of-absence" required>
        <option value="">Select</option>
        <option value="illness">Illness</option>
        <option value="injury">Injury</option>
        <option value="other">Other</option>
    </select>
    <label for="details">Details</label>
    <textarea id="details"></textarea>
    <label for="documents">Upload Documents</label>
    <input type="file" id="documents" multiple onchange="updateFileList()">
    <ul id="documents-list"></ul>
    <button type="button" onclick="submitForm()">Submit</button>
</div>

<div id="confirmation">
    <h2>Claim Submitted</h2>
    <p>Reference Number: <span id="reference-number"></span></p>
    <p>Status: Received</p>
</div>

<footer>MapleSure Insurance — fictional demo application</footer>

<script>
    var mockData = {
        '12345': { name: 'John Doe', dob: '1980-01-01', policy: 'Policy A' },
        '67890': { name: 'Jane Smith', dob: '1975-05-15', policy: 'Policy B' }
    };

    function lookupMember() {
        var memberId = document.getElementById('member-id').value;
        var detailsDiv = document.getElementById('member-details');

        if(mockData[memberId]) {
            var member = mockData[memberId];
            detailsDiv.innerHTML = 'Name: ' + member.name + '<br>Date of Birth: ' + member.dob + '<br>Policy: ' + member.policy;
        } else {
            detailsDiv.innerHTML = 'Member not found.';
        }
    }

    function updateFileList() {
        var input = document.getElementById('documents');
        var list = document.getElementById('documents-list');

        list.innerHTML = '';
        for (var i = 0; i < input.files.length; ++i) {
            var li = document.createElement('li');
            li.textContent = input.files[i].name;
            list.appendChild(li);
        }
    }

    function submitForm() {
        document.getElementById('claim-form').style.display = 'none';
        document.getElementById('confirmation').style.display = 'block';

        var refNumber = 'MS-2026-08-' + Math.floor(1000 + Math.random() * 9000);
        document.getElementById('reference-number').textContent = refNumber;
    }
</script>

</body>
